workspace "Bookshop" "A simple online bookshop" {
    model {
        customer = person "Customer" "A customer who browses and orders books"
        bookshop = softwareSystem "Bookshop" "A simple online bookshop" {
            webApp = container "Web App" "Serves the bookshop's catalogue and checkout to customers" "React"
            api = container "API" "Exposes the catalogue and order services over HTTP" "Node.js" {
                catalogueController = component "Catalogue Controller" "Handles requests for book details" "Express Router"
                orderController = component "Order Controller" "Handles checkout and order placement" "Express Router"
            }
            db = container "Database" "Stores books, customers and orders" "PostgreSQL"
        }

        customer -> webApp "Browses the catalogue and places orders through" "HTTPS"
        webApp -> api "Sends REST requests to" "HTTPS/JSON"
        api -> db "Reads and writes catalogue and order data in" "JDBC"
        orderController -> catalogueController "Looks up book prices from" "In-process call"
        catalogueController -> db "Reads books from" "TypeORM"
        orderController -> db "Writes orders to" "TypeORM"
    }
    views {
        systemContext bookshop "SystemContext" {
            include *
            autoLayout
        }
        container bookshop "Containers" {
            include *
            autoLayout
        }
        component api "ApiComponents" {
            include *
            autoLayout
        }
    }
    configuration {
        scope softwaresystem
    }
}

